import pytest

@pytest.mark.parametrize("pet_id, name, status, expected_status_code", [
    (1, "Doggie", "available", 200),
    (2, None, "sold", 200),
    (3, "Kitty", None, 200),
    (4, None, None, 200),
    (5, "InvalidPet", "unknown", 405),
])
def test_update_pet_with_form(api_client, valid_api_key, pet_id, name, status, expected_status_code):
    """
    Test updating a pet with form data.
    """
    endpoint = f"v2/pet/{pet_id}"
    headers = {
        "Authorization": f"Bearer {valid_api_key}",
        "Content-Type": "application/x-www-form-urlencoded"
    }
    data = {}
    if name:
        data['name'] = name
    if status:
        data['status'] = status

    response = api_client.make_request(endpoint, params=data, headers=headers, method='POST')
    assert response.status_code == expected_status_code

